11: async function gql(env, query, variables) {
12:   const resp = await fetch(GQL, {
13:     method: 'POST',
14:     headers: { Authorization: authH(env), 'Content-Type': 'application/json' },
15:     body: JSON.stringify({ query, variables }),
16:   });
17:   const body = await resp.json();
18:   if (body.errors) throw new Error(`fly graphql: ${body.errors[0].message}`);
19:   return body.data;
20: }
