53:     { input: { name: `small-${flyApp}`, organizationId: await orgId(env), profile: 'deploy', profileParams: { app_id: flyApp }, expiry: '1h0m0s' } }
54:   );
55:   return data.createLimitedAccessToken.limitedAccessToken.tokenHeader;
56: }"}},"label":"answer-1","response":{"answer":"There's no recorded experiment comparing durations. The 1-hour expiry appears to be the value chosen from the start of the fallback plan (m1824, m1940, m1953) and carried straight into the shipped code (`expiry: '1h0m0s'` in packages/control-plane/src/fly.js:53). The rationale given throughout is only that the token should be short-lived and scoped to a single app — no builder note explains why 1h specifically was picked over 30m or any other window, and no A/B or timing test is recorded. If you need a tighter window, the next step would be to check whether flyctl deploy of typical app sizes reliably completes well under 30 minutes, then adjust the `expiry` param in `mintDeployToken` accordingly.","citations":[{"kind":"message","message_id":"m1824"},{"kind":"message","message_id":"m1940"},{"end_line":56,"kind":"code","path":"packages/control-plane/src/fly.js","start_line":48}]}},{"available_context":{"snapshot":"f9026a7607eb9b3542b1918c3360d3718c8c1bda","sources":{"packages/cli/lib/fly.js":"1: 'use strict';
